65. // GetInstances returns the list of all instances including their ENIs as instanceMap
66. func (c *Client) GetInstances(ctx context.Context, vpcs ipamTypes.VirtualNetworkMap, subnets ipamTypes.SubnetMap) (*ipamTypes.InstanceMap, error) {
67. 	instances := ipamTypes.NewInstanceMap()
68. 
69. 	networkInterfaceSets, err := c.describeNetworkInterfaces(ctx)
70. 	if err != nil {
71. 		return nil, err
72. 	}
73. 
74. 	for _, iface := range networkInterfaceSets {
75. 		id, eni, err := parseENI(&iface, vpcs, subnets)
76. 		if err != nil {
77. 			return nil, err
78. 		}
79. 
80. 		instances.Update(id, ipamTypes.InterfaceRevision{
81. 			Resource: eni,
82. 		})
83. 	}
84. 	return instances, nil
85. }
