87. // GetVSwitches returns all ecs vSwitches as a subnetMap
88. func (c *Client) GetVSwitches(ctx context.Context) (ipamTypes.SubnetMap, error) {
89. 	var result ipamTypes.SubnetMap
90. 	for i := 1; ; {
91. 		req := vpc.CreateDescribeVSwitchesRequest()
92. 		req.PageNumber = requests.NewInteger(i)
93. 		req.PageSize = requests.NewInteger(50)
94. 		c.limiter.Limit(ctx, "DescribeVSwitches")
95. 		resp, err := c.vpcClient.DescribeVSwitches(req)
96. 		if err != nil {
97. 			return nil, err
98. 		}
99. 		if len(resp.VSwitches.VSwitch) == 0 {
100. 			break
101. 		}
102. 		if result == nil {
103. 			result = make(ipamTypes.SubnetMap, resp.TotalCount)
104. 		}
105. 
106. 		for _, v := range resp.VSwitches.VSwitch {
107. 			_, ipnet, err := net.ParseCIDR(v.CidrBlock)
108. 			if err != nil {
109. 				return nil, err
110. 			}
111. 			result[v.VSwitchId] = &ipamTypes.Subnet{
112. 				ID:                 v.VSwitchId,
113. 				Name:               v.VSwitchName,
114. 				CIDR:               cidr.NewCIDR(ipnet),
115. 				AvailabilityZone:   v.ZoneId,
116. 				VirtualNetworkID:   v.VpcId,
117. 				AvailableAddresses: int(v.AvailableIpAddressCount),
118. 				Tags:               map[string]string{},
119. 			}
120. 			for _, tag := range v.Tags.Tag {
121. 				result[v.VSwitchId].Tags[tag.Key] = tag.Value
122. 			}
123. 		}
124. 		if resp.TotalCount < resp.PageNumber*resp.PageSize {
125. 			break
126. 		}
127. 		i++
128. 	}
129. 
130. 	return result, nil
131. }
