240. // CreateNetworkInterface creates an ENI with the given parameters
241. func (c *Client) CreateNetworkInterface(ctx context.Context, secondaryPrivateIPCount int, vSwitchID string, groups []string, tags map[string]string) (string, *eniTypes.ENI, error) {
242. 	req := ecs.CreateCreateNetworkInterfaceRequest()
243. 	// SecondaryPrivateIpAddressCount is optional but must not be zero
244. 	if secondaryPrivateIPCount > 0 {
245. 		req.SecondaryPrivateIpAddressCount = requests.NewInteger(secondaryPrivateIPCount)
246. 	}
247. 	req.VSwitchId = vSwitchID
248. 	req.SecurityGroupIds = &groups
249. 	reqTag := make([]ecs.CreateNetworkInterfaceTag, 0, len(tags))
250. 	for k, v := range tags {
251. 		reqTag = append(reqTag, ecs.CreateNetworkInterfaceTag{
252. 			Key:   k,
253. 			Value: v,
254. 		})
255. 	}
256. 	req.Tag = &reqTag
257. 
258. 	c.limiter.Limit(ctx, "CreateNetworkInterface")
