 func (a *API) DeleteNetworkInterface(ctx context.Context, eniID string) error {
 	a.mutex.Lock()
 	defer a.mutex.Unlock()

 	delete(a.unattached, eniID)
 	for _, enis := range a.enis {
 		if _, ok := enis[eniID]; ok {
